#!/usr/bin/env python3
import argparse
import json
from pathlib import Path
import subprocess
import sys
import tempfile


def write_json(path: Path, value: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False), encoding="utf-8")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--skill-dir", type=Path, required=True)
    args = parser.parse_args()
    script = args.skill_dir.resolve() / "scripts" / "prune_system_ui_components.py"

    with tempfile.TemporaryDirectory(prefix="iff-prune-system-ui-") as raw_tmp:
        project = Path(raw_tmp)
        scene = project / "spec" / "scene.json"
        registry = project / ".iff" / "shared_components.json"
        report = project / ".iff" / "system_ui_prune_report.json"
        system_widget = project / "lib/shared/widgets/system_header.dart"
        system_test = project / "test/shared/widgets/system_header_test.dart"
        system_expected = project / "lib/shared/widgets/system_header.dart.expected.json"
        system_asset = project / "assets/iff_shared/system_header/status.png"
        app_widget = project / "lib/shared/widgets/app_header.dart"
        app_asset = project / "assets/iff_shared/app_header/logo.png"
        pubspec = project / "pubspec.yaml"

        write_json(
            scene,
            {
                "systemUiExclusions": [
                    {"node": "sys-time", "role": "status_bar"},
                    {"node": "sys-icons", "role": "status_bar"},
                ]
            },
        )
        write_json(
            registry,
            {
                "components": {
                    "system-signature": {
                        "widget_path": "lib/shared/widgets/system_header.dart",
                        "source_spec_dir": str(scene.parent),
                        "canonical_nodes": ["sys-time", "sys-icons"],
                        "assets": ["assets/iff_shared/system_header/status.png"],
                    },
                    "mixed-signature": {
                        "widget_path": "lib/shared/widgets/app_header.dart",
                        "source_spec_dir": str(scene.parent),
                        "canonical_nodes": ["sys-time", "app-title"],
                        "assets": [],
                    },
                    "foreign-signature": {
                        "widget_path": "lib/shared/widgets/foreign_header.dart",
                        "source_spec_dir": str(project / "other-spec"),
                        "canonical_nodes": ["sys-time", "sys-icons"],
                        "assets": [],
                    },
                }
            },
        )
        system_widget.parent.mkdir(parents=True, exist_ok=True)
        system_widget.write_text("// GENERATED by iFF generate_canvas.py — DO NOT EDIT BY HAND.\n", encoding="utf-8")
        system_test.parent.mkdir(parents=True, exist_ok=True)
        system_test.write_text(
            "// GENERATED by iFF generate_shared_component_test.py — DO NOT EDIT BY HAND.\n",
            encoding="utf-8",
        )
        write_json(system_expected, {"nodes": {}})
        system_asset.parent.mkdir(parents=True, exist_ok=True)
        system_asset.write_bytes(b"png")
        app_widget.write_text("// GENERATED by iFF generate_canvas.py — DO NOT EDIT BY HAND.\n", encoding="utf-8")
        app_asset.parent.mkdir(parents=True, exist_ok=True)
        app_asset.write_bytes(b"png")
        pubspec.write_text(
            "flutter:\n"
            "  assets:\n"
            "    - assets/iff_shared/system_header/\n"
            "    - assets/iff_shared/app_header/\n",
            encoding="utf-8",
        )

        completed = subprocess.run(
            [
                sys.executable,
                str(script),
                "--project-root",
                str(project),
                "--scene",
                str(scene),
                "--registry",
                str(registry),
                "--out",
                str(report),
                "--apply",
            ],
            text=True,
            capture_output=True,
            check=False,
        )
        assert completed.returncode == 0, completed.stderr
        assert not system_widget.exists()
        assert not system_test.exists()
        assert not system_expected.exists()
        assert not system_asset.exists()
        assert app_widget.exists()
        assert app_asset.exists()
        pubspec_text = pubspec.read_text(encoding="utf-8")
        assert "assets/iff_shared/system_header/" not in pubspec_text
        assert "assets/iff_shared/app_header/" in pubspec_text
        components = json.loads(registry.read_text(encoding="utf-8"))["components"]
        assert set(components) == {"mixed-signature", "foreign-signature"}
        result = json.loads(report.read_text(encoding="utf-8"))
        assert result["removedSignatures"] == ["system-signature"]

        missing_registry = project / ".iff" / "new_project_registry.json"
        first_run_report = project / ".iff" / "first_run_prune_report.json"
        first_run = subprocess.run(
            [
                sys.executable,
                str(script),
                "--project-root",
                str(project),
                "--scene",
                str(scene),
                "--registry",
                str(missing_registry),
                "--out",
                str(first_run_report),
                "--apply",
            ],
            text=True,
            capture_output=True,
            check=False,
        )
        assert first_run.returncode == 0, first_run.stderr
        assert not missing_registry.exists()
        assert json.loads(first_run_report.read_text(encoding="utf-8"))["removedSignatures"] == []

    print("OK: only generated shared components made entirely of excluded system UI are retired")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
